-- Rebuild Medina Book 4 lesson 5 strictly from the supplied Arabic sharh.
-- Canonical PDF pages: 21-23. DOC text was used only for extraction and checked against the PDF.
begin;

do $migration$
declare
  existing_count integer;
begin
  select count(*) into existing_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '5';
  if existing_count <> 6 then
    raise exception 'Expected 6 Book 4 lesson 5 rules, found %', existing_count;
  end if;
end $migration$;

with incoming(sort_order, title, content, summary, rule_ar) as (
  values
    (1, 'بَابُ اِنْفَعَلَ (порода اِنْفَعَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ اِنْفَعَلَ مَزِيدٌ بِهَمْزَةِ الْوَصْلِ وَالنُّونِ، وَمَصْدَرُهُ عَلَى وَزْنِ اِنْفِعَالٍ، وَمَعْنَاهُ الْمُطَاوَعَةُ، وَلَا يَكُونُ إِلَّا لَازِمًا. وَفِي مَصْدَرِ كُلِّ فِعْلٍ مَبْدُوءٍ بِهَمْزَةِ وَصْلٍ يُكْسَرُ الْحَرْفُ الثَّالِثُ وَتُزَادُ أَلِفٌ قَبْلَ الْآخِرِ. وَإِذَا دَخَلَتْ هَمْزَةُ الِاسْتِفْهَامِ عَلَى هَمْزَةِ الْوَصْلِ حُذِفَتْ هَمْزَةُ الْوَصْلِ.</span><p class="rule-study-text">Порода اِنْفَعَلَ содержит добавочные هَمْزَةُ الْوَصْلِ и ن, выражает принятие результата действия и бывает только непереходной. Шарх отдельно объясняет образование масдара и удаление هَمْزَةُ الْوَصْلِ после вопросительной хамзы.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">حَرْفَا الزِّيَادَةِ: هَمْزَةُ الْوَصْلِ وَالنُّونُ</span><span class="rule-term-ru">добавочные элементы — соединительная хамза и ن</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ: اِنْفِعَالٌ</span><span class="rule-term-ru">масдар по модели اِنْفِعَالٌ</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْمُطَاوَعَةُ</span><span class="rule-term-ru">принятие результата действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">لَازِمٌ</span><span class="rule-term-ru">порода бывает только непереходной</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Значение الْمُطَاوَعَةُ</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">كَسَرْتُ الزُّجَاجَ، فَانْكَسَرَ الزُّجَاجُ.</span><span class="rule-example-ru">Я разбил стекло, и стекло разбилось.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">فَتَحْتُ الْبَابَ، فَانْفَتَحَ الْبَابُ.</span><span class="rule-example-ru">Я открыл дверь, и дверь открылась.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Производные формы шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедшее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настояще-будущее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْرُ</span><span class="rule-table-ru">повелительное</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-table-ru">действующее причастие</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِنْفَتَحَ</span><span class="rule-table-ru">открылся</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَنْفَتِحُ</span><span class="rule-table-ru">открывается</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِنْفَتِحْ</span><span class="rule-table-ru">откройся</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِنْفِتَاحٌ</span><span class="rule-table-ru">открытие</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُنْفَتِحٌ</span><span class="rule-table-ru">открывающийся, открытый</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِنْقَطَعَ</span><span class="rule-table-ru">оборвался</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَنْقَطِعُ</span><span class="rule-table-ru">обрывается</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِنْقَطِعْ</span><span class="rule-table-ru">оборвись</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِنْقِطَاعٌ</span><span class="rule-table-ru">обрыв, прекращение</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُنْقَطِعٌ</span><span class="rule-table-ru">оборвавшийся, прекратившийся</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِنْجَلَى</span><span class="rule-table-ru">прояснился</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَنْجَلِي</span><span class="rule-table-ru">проясняется</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِنْجَلِ</span><span class="rule-table-ru">прояснись</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِنْجِلَاءٌ</span><span class="rule-table-ru">прояснение</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُنْجَلٍ (الْمُنْجَلِي)</span><span class="rule-table-ru">проясняющийся, ясный</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Вопросительная хамза и هَمْزَةُ الْوَصْلِ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْخَبَرُ</span><span class="rule-table-ru">сообщение</span></th><th><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الِاسْتِفْهَامُ</span><span class="rule-table-ru">вопрос после удаления هَمْزَةُ الْوَصْلِ</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِنْفَتَحَ الْبَابُ.</span><span class="rule-table-ru">дверь открылась</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَنْفَتَحَ الْبَابُ؟</span><span class="rule-table-ru">открылась ли дверь?</span></td><td><span class="rule-table-ru">соединительная хамза удалена; осталась вопросительная أَ</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِنْقَطَعَ الْحَبْلُ.</span><span class="rule-table-ru">верёвка оборвалась</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَنْقَطَعَ الْحَبْلُ؟</span><span class="rule-table-ru">оборвалась ли верёвка?</span></td><td><span class="rule-table-ru">соединительная хамза удалена; осталась вопросительная أَ</span></td></tr></tbody></table></div></div></div>', 'Порода اِنْفَعَلَ содержит добавочные هَمْزَةُ الْوَصْلِ и ن, выражает принятие результата действия и бывает только непереходной. Шарх отдельно объясняет образование масдара и удаление هَمْزَةُ الْوَصْلِ после вопросительной хамзы.', 'بَابُ اِنْفَعَلَ مَزِيدٌ بِهَمْزَةِ الْوَصْلِ وَالنُّونِ، وَمَصْدَرُهُ عَلَى وَزْنِ اِنْفِعَالٍ، وَمَعْنَاهُ الْمُطَاوَعَةُ، وَلَا يَكُونُ إِلَّا لَازِمًا. وَفِي مَصْدَرِ كُلِّ فِعْلٍ مَبْدُوءٍ بِهَمْزَةِ وَصْلٍ يُكْسَرُ الْحَرْفُ الثَّالِثُ وَتُزَادُ أَلِفٌ قَبْلَ الْآخِرِ. وَإِذَا دَخَلَتْ هَمْزَةُ الِاسْتِفْهَامِ عَلَى هَمْزَةِ الْوَصْلِ حُذِفَتْ هَمْزَةُ الْوَصْلِ.'),
    (2, 'لَوْلَا (частица невозможности вследствие наличия — «если бы не»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">لَوْلَا حَرْفُ امْتِنَاعٍ لِوُجُودٍ يَتَضَمَّنُ مَعْنَى الشَّرْطِ، وَهُوَ غَيْرُ جَازِمٍ. يَقْتَرِنُ جَوَابُهَا الْمُثْبَتُ بِاللَّامِ، وَيُعْرَبُ مَا بَعْدَهَا مُبْتَدَأً خَبَرُهُ مَحْذُوفٌ تَقْدِيرُهُ مَوْجُودٌ. وَيَجُوزُ أَنْ تَدْخُلَ عَلَيْهَا أَنَّ الْمَصْدَرِيَّةُ مَعَ اسْمِهَا وَخَبَرِهَا.</span><p class="rule-study-text">لَوْلَا связывает отсутствие результата с наличием названной причины. В утвердительном ответе появляется لَـ, после частицы стоит подлежащее с опущенным сказуемым «существует». Вместо отдельного имени может идти конструкция أَنَّ с именем и сказуемым.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ امْتِنَاعٍ لِوُجُودٍ</span><span class="rule-term-ru">частица невозможности одного из-за наличия другого</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">غَيْرُ جَازِمٍ</span><span class="rule-term-ru">не ставит глагол в усечённое наклонение</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">الْخَبَرُ مَحْذُوفٌ تَقْدِيرُهُ مَوْجُودٌ</span><span class="rule-term-ru">сказуемое опущено; подразумевается «существует»</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Утвердительный и отрицательный ответ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ الْجَوَابِ</span><span class="rule-table-ru">вид ответа</span></th><th><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مُثْبَتٌ مَقْرُونٌ بِاللَّامِ</span><span class="rule-table-ru">утвердительный ответ с لَـ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَوْلَا الْإِسْلَامُ لَضَلَلْنَا.</span><span class="rule-table-ru">لَـ стоит при ответе</span></td><td><span class="rule-table-ru">Если бы не ислам, мы заблудились бы.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مُثْبَتٌ مَقْرُونٌ بِاللَّامِ</span><span class="rule-table-ru">утвердительный ответ с لَـ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَوْلَا الْعِلْمُ لَجَهِلْنَا.</span><span class="rule-table-ru">لَـ стоит при ответе</span></td><td><span class="rule-table-ru">Если бы не знание, мы остались бы невеждами.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْفِيٌّ</span><span class="rule-table-ru">отрицательный ответ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَوْلَا اللَّهُ مَا اهْتَدَيْنَا.</span><span class="rule-table-ru">ответ с отрицанием مَا</span></td><td><span class="rule-table-ru">Если бы не Аллах, мы не были бы наставлены.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْفِيٌّ</span><span class="rule-table-ru">отрицательный ответ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَوْلَا الْعِلْمُ مَا عَرَفْنَا شَيْئًا.</span><span class="rule-table-ru">ответ с отрицанием مَا</span></td><td><span class="rule-table-ru">Если бы не знание, мы ничего не узнали бы.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">أَنَّ الْمَصْدَرِيَّةُ после لَوْلَا</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">لَوْلَا أَنَّ الْبَرْدَ شَدِيدٌ لَخَرَجْتُ مِنَ الْبَيْتِ.</span><span class="rule-example-ru">Если бы не сильный холод, я вышел бы из дома.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">التَّقْدِيرُ: لَوْلَا شِدَّةُ الْبَرْدِ لَخَرَجْتُ مِنَ الْبَيْتِ.</span><span class="rule-example-ru">Восстановленная именная форма: «если бы не сила холода…».</span></div></div></div></div>', 'لَوْلَا связывает отсутствие результата с наличием названной причины. В утвердительном ответе появляется لَـ, после частицы стоит подлежащее с опущенным сказуемым «существует». Вместо отдельного имени может идти конструкция أَنَّ с именем и сказуемым.', 'لَوْلَا حَرْفُ امْتِنَاعٍ لِوُجُودٍ يَتَضَمَّنُ مَعْنَى الشَّرْطِ، وَهُوَ غَيْرُ جَازِمٍ. يَقْتَرِنُ جَوَابُهَا الْمُثْبَتُ بِاللَّامِ، وَيُعْرَبُ مَا بَعْدَهَا مُبْتَدَأً خَبَرُهُ مَحْذُوفٌ تَقْدِيرُهُ مَوْجُودٌ. وَيَجُوزُ أَنْ تَدْخُلَ عَلَيْهَا أَنَّ الْمَصْدَرِيَّةُ مَعَ اسْمِهَا وَخَبَرِهَا.'),
    (3, 'لَوْمَا (частица, равная لَوْلَا в этом употреблении)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">لَوْمَا مِثْلُ لَوْلَا فِي مَعْنَى الِامْتِنَاعِ لِوُجُودٍ وَفِي أَحْكَامِهَا.</span><p class="rule-study-text">В объяснённом автором употреблении لَوْمَا имеет то же значение и те же правила, что لَوْلَا.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">لَوْمَا الْإِسْلَامُ لَضَلَلْنَا.</span><span class="rule-example-ru">Если бы не ислам, мы заблудились бы.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">لَوْمَا الْعِلْمُ مَا عَرَفْنَا شَيْئًا.</span><span class="rule-example-ru">Если бы не знание, мы ничего не узнали бы.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор لَوْمَا الْإِسْلَامُ لَضَلَلْنَا</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">لَوْمَا، أَوْ لَوْلَا: حَرْفُ امْتِنَاعٍ لِوُجُودٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">لَوْمَا или لَوْلَا — неизменяемая на сукуне частица невозможности одного из-за наличия другого; синтаксического места не имеет.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">الْإِسْلَامُ: مُبْتَدَأٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ، وَالْخَبَرُ مَحْذُوفٌ تَقْدِيرُهُ مَوْجُودٌ.</span><span class="rule-example-ru">الْإِسْلَامُ — подлежащее в именительном статусе с явной даммой; сказуемое опущено, подразумевается «существует».</span></div><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">لَضَلَلْنَا: اللَّامُ حَرْفُ جَوَابٍ وَرَبْطٍ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَجُمْلَةُ الْجَوَابِ مِنَ الْفِعْلِ وَالْفَاعِلِ «لَضَلَلْنَا» لَا مَحَلَّ لَهَا مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">В لَضَلَلْنَا начальная لَـ — неизменяемая на фатхе частица ответа и связи без синтаксического места; всё предложение ответа из глагола и исполнителя также не имеет синтаксического места.</span></div></div></div></div>', 'В объяснённом автором употреблении لَوْمَا имеет то же значение и те же правила, что لَوْلَا.', 'لَوْمَا مِثْلُ لَوْلَا فِي مَعْنَى الِامْتِنَاعِ لِوُجُودٍ وَفِي أَحْكَامِهَا.'),
    (4, 'إِعْرَابُ اسْمِ الْإِشَارَةِ نَعْتًا (разбор указательного имени как определения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-predicate" dir="rtl" lang="ar">يُعْرَبُ اسْمُ الْإِشَارَةِ نَعْتًا إِذَا وَقَعَ بَعْدَ الْعَلَمِ أَوِ الْمُعَرَّفِ بِالْإِضَافَةِ.</span><p class="rule-study-text">Указательное имя, поставленное после имени собственного либо после определённого через идафу имени, разбирается как согласованное определение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два положения</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا قَبْلَ اسْمِ الْإِشَارَةِ</span><span class="rule-table-ru">что стоит перед указательным именем</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُ اسْمِ الْإِشَارَةِ</span><span class="rule-table-ru">разбор</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْعَلَمُ</span><span class="rule-table-ru">имя собственное</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَنْ إِبْرَاهِيمُ هَذَا؟</span><span class="rule-table-ru">Кто этот Ибрахим?</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">هَذَا: اسْمُ إِشَارَةٍ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ نَعْتٌ.</span><span class="rule-table-ru">هَذَا — указательное имя на сукуне в именительном месте определения.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُعَرَّفُ بِالْإِضَافَةِ</span><span class="rule-table-ru">имя, определённое идафой</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">أَرِنِي سَاعَتَكَ هَذِهِ.</span><span class="rule-table-ru">Покажи мне эти твои часы.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">هَذِهِ: اسْمُ إِشَارَةٍ مَبْنِيٌّ عَلَى الْكَسْرِ فِي مَحَلِّ نَصْبٍ نَعْتٌ.</span><span class="rule-table-ru">هَذِهِ — указательное имя на касре в винительном месте определения.</span></td></tr></tbody></table></div></div></div>', 'Указательное имя, поставленное после имени собственного либо после определённого через идафу имени, разбирается как согласованное определение.', 'يُعْرَبُ اسْمُ الْإِشَارَةِ نَعْتًا إِذَا وَقَعَ بَعْدَ الْعَلَمِ أَوِ الْمُعَرَّفِ بِالْإِضَافَةِ.'),
    (5, 'التَّغْلِيبُ (преобладание одной формы над другой)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">التَّغْلِيبُ هُوَ تَفْضِيلُ أَحَدِ لَفْظَيْنِ أَوْ تَقْدِيمُهُ عَلَى الْآخَرِ. وَيُغَلَّبُ الْمُذَكَّرُ عَلَى الْمُؤَنَّثِ، فَيَأْتِي الْخَبَرُ بِلَفْظِ الْمُذَكَّرِ.</span><p class="rule-study-text">При совместном упоминании мужского и женского мужская форма получает преобладание, поэтому сказуемое употребляется в мужском роде. Тем же принципом объясняются некоторые двойственные названия.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Преобладание мужского рода</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">أَبْنَائِي وَبَنَاتِي يَدْرُسُونَ.</span><span class="rule-example-ru">Мои сыновья и дочери учатся: يَدْرُسُونَ стоит в мужской форме.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">النِّسَاءُ وَالرِّجَالُ يُصَلُّونَ.</span><span class="rule-example-ru">Женщины и мужчины молятся: يُصَلُّونَ стоит в мужской форме.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Двойственные названия по принципу التَّغْلِيبُ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اللَّفْظُ</span><span class="rule-table-ru">форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا يَشْمَلُهُ</span><span class="rule-table-ru">что она объединяет</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَبَوَانِ</span><span class="rule-table-ru">двойственное от «отец»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَبُ وَالْأُمُّ</span><span class="rule-table-ru">отец и мать</span></td><td><span class="rule-table-ru">родители</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقَمَرَانِ</span><span class="rule-table-ru">двойственное от «луна»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّمْسُ وَالْقَمَرُ</span><span class="rule-table-ru">солнце и луна</span></td><td><span class="rule-table-ru">два светила</span></td></tr></tbody></table></div></div></div>', 'При совместном упоминании мужского и женского мужская форма получает преобладание, поэтому сказуемое употребляется в мужском роде. Тем же принципом объясняются некоторые двойственные названия.', 'التَّغْلِيبُ هُوَ تَفْضِيلُ أَحَدِ لَفْظَيْنِ أَوْ تَقْدِيمُهُ عَلَى الْآخَرِ. وَيُغَلَّبُ الْمُذَكَّرُ عَلَى الْمُؤَنَّثِ، فَيَأْتِي الْخَبَرُ بِلَفْظِ الْمُذَكَّرِ.'),
    (6, 'إِضَافَةُ الظَّرْفِ إِلَى الْجُمْلَةِ (идафа обстоятельства к предложению)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-jarr" dir="rtl" lang="ar">تُعْرَبُ الْجُمْلَةُ الْوَاقِعَةُ بَعْدَ الظَّرْفِ مُضَافًا إِلَيْهِ فِي مَحَلِّ جَرٍّ.</span><p class="rule-study-text">Предложение после обстоятельства времени занимает родительное место второй части идафы.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">предложение и перевод</span></th><th><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الظَّرْفُ</span><span class="rule-table-ru">обстоятельство</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجُمْلَةُ الْمُضَافَةُ إِلَيْهِ</span><span class="rule-table-ru">предложение в родительном месте</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَاتَ إِبْرَاهِيمُ يَوْمَ انْكَسَفَتِ الشَّمْسُ.</span><span class="rule-table-ru">Ибрахим умер в день, когда произошло солнечное затмение.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">يَوْمَ</span><span class="rule-table-ru">в день</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">انْكَسَفَتِ الشَّمْسُ</span><span class="rule-table-ru">«произошло солнечное затмение» — в родительном месте второй части идафы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَافَرْتُ يَوْمَ ظَهَرَتِ النَّتَائِجُ.</span><span class="rule-table-ru">Я отправился в путь в день, когда появились результаты.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">يَوْمَ</span><span class="rule-table-ru">в день</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ظَهَرَتِ النَّتَائِجُ</span><span class="rule-table-ru">«появились результаты» — в родительном месте</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وُلِدْتُ يَوْمَ زَارَ الْوَزِيرُ الْجَامِعَةَ.</span><span class="rule-table-ru">Я родился в день, когда министр посетил университет.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">يَوْمَ</span><span class="rule-table-ru">в день</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">زَارَ الْوَزِيرُ الْجَامِعَةَ</span><span class="rule-table-ru">«министр посетил университет» — в родительном месте</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿يَوۡمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمۡتَلَأۡتِ﴾</span><span class="rule-example-ru">В тот День Мы скажем Геенне: «Наполнилась ли ты?» Предложение после يَوْمَ занимает родительное место второй части идафы.</span></div></div></div></div>', 'Предложение после обстоятельства времени занимает родительное место второй части идафы.', 'تُعْرَبُ الْجُمْلَةُ الْوَاقِعَةُ بَعْدَ الظَّرْفِ مُضَافًا إِلَيْهِ فِي مَحَلِّ جَرٍّ.')
)
update public.rules as r
set title = incoming.title,
    content = incoming.content,
    rule_kind = 'rule',
    summary = incoming.summary,
    rule_ar = incoming.rule_ar
from incoming
where r.course_name = 'Мединский курс (Том 4)'
  and r.lesson_number = '5'
  and r.sort_order = incoming.sort_order;

delete from public.rule_sources
where rule_id in (
  select id from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '5'
);

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الدَّرْسُ الْخَامِسُ
بَـابُ اِنْفَعَلَ
من أمثلته : اِنْفَتَحَ ، اِنْكَسَرَ ، اِنْقَطَعَ ، اِنْجَلَى .
حرفا الزيادة : الهمزة ، والنون .
مصدره :  اِنْفِعَالٌ ( كلّ فعل بُدِئَ بهمزة وصل كُسِرَ الحرف الثالث ، وزِيدَتْ ألف قبل آخره ) ، نحو : اِنْقَطَعَ : اِنْقِطَاعٌ ، اِنْكَسَرَ : اِنْكِسَارٌ .
معناه : الْمُطَاوَعَةُ .
نحو : كَسَرْتُ الزُّجاجَ ، فَانْكَسَرَ الزّجاجُ . فَتَحْتُ البابَ ، فَانْفَتَحَ البابُ .
المشتقات :                   ( هذا الباب لا يكون إلا لازما )
اسم الفاعل
