إذا دخلتْ همزةُ الاستفهامِ على همزةِ الوَصْلِ حُذِفَتْ همزةُ الوصلِ ، نحو :
انفَتَحَ البابُ . أَنْفَتَحَ البابُ ؟        انْقَطَعَ الْحَبْلُ . أَنْقَطَعَ الحبلُ ؟', 21, 21, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '5' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'لَوْلاَ
لولا : حرف امتناع لوجود ، تتضمَّن معنى الشَّرط ، وهي حرف غير جازم ، يقترن جوابها المثبت باللام ، ويُعْرَبُ ما بعدها مبتدأ خبره محذوف ، تقديره ( موجود ) .
الأمثلة :
لولا الإسلامُ لَضَلَلْنَا   .     لولا العِلْمُ لَجَهِلْناَ .
لولا اللهُ ما اهْتَدَيْنَا     .    لولا العِلْمُ ما عَرَفْناَ شيئاً .
يجوز أن تدخل عليها أنَّ المصدريّة واسمها ، وخبرها .
نحو : لولا أنَّ البردَ شديدٌ لَخَرَجْتُ من البيت ، والتقدير : لولا شِدَّةُ البردِ لخرجت من البيت .', 21, 22, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '5' and sort_order = 2;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'لَوْمَا
لَوْمَا مِثْلُ ( لَوْلاَ ) ؛ تقول : لوما الإسلامُ لَضَلَلْناَ . لوما العِلْمُ ما عَرَفْنَا شيئاً .
الإعراب : لوما الإسلام لضللنا :
لوما ، أو لولا : حرف امتناع لوجود مبني على السكون لا محل له من الإعراب .
الإسلامُ : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة، والخبر محذوف تقديره ( موجود ) .
لضللنا : اللام حرف جواب وربط مبني على الفتح لا محل له من الإعراب ، وجملة الجواب من الفعل والفاعل ( لضللنا ) لا محل لها من الإعراب .', 22, 22, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '5' and sort_order = 3;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'إعراب اسم الإشارة نعتا
يُعْرَبُ اسمُ الإشارةِ نعتاً إذا وقع بعد :
1- العَلَم ، نحو : من إبراهيمُ هذا ؟                                                             هذاْ : اسم إشارة مبني على السكون في محل رفع نعت .
2- الْمُعَرَّف بالإضافة : نحو : أرني ساعتَكَ هذهِ .                                             هذهِ : اسم إشارة مبني على الكسر في محل نصب نعت .', 22, 22, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '5' and sort_order = 4;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'التَّغْلِيبُ
التَّغليبُ ، هو : تفضيل ، أو تقديم أحد لفظين على الآخر .
يُغَلَّبُ الْمُذَكَّرُ على الْمُؤنَّثِ ؛ تقول : أبنائي وبناتي يدرسون ؛ وتقول : النساء والرجال يُصَلّون .
فالخبر ( يدرسون ، ويصلون ) جَاءَ بلفظ المذكَّر تغليباً .
ومن التغليب أيضاً قولهم : الأَبَوَانِ ( للأب ، والأم ) والْقَمَرَانِ ( للشمس ، والقمر ) .', 22, 23, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '5' and sort_order = 5;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'إضافةُ الظرف إلى الجملة
تُعْرَبُ الجملة الواقعة بعد الظرف : مضافاً إليه في محل جرّ , نحو : مات إبراهيمُ يومَ انْكَسَفَتِ الشَّمسُ . فجملة ( انكسفت الشمس ) في محل جرٍّ مضاف إليه ؛ لِوقوعها بعد الظرف ( يوم ) .
ومن ذلك قولك : سافرتُ يومَ ظهرتِ النتائج . وُلِدْتُ يومَ زار الوزيرُ الجامعة .       ومنه قوله تعالى : ﴿ يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ امْتَلَأْتِ ... ﴾  .', 23, 23, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '5' and sort_order = 6;

do $migration$
declare
  updated_count integer;
  source_count integer;
begin
  select count(*) into updated_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '5' and rule_ar is not null and btrim(rule_ar) <> '';
  select count(*) into source_count
  from public.rule_sources rs
  join public.rules r on r.id = rs.rule_id
  where r.course_name = 'Мединский курс (Том 4)' and r.lesson_number = '5';
  if updated_count <> 6 or source_count <> 6 then
    raise exception 'Book 4 lesson 5 QA failed: rules %, sources %', updated_count, source_count;
  end if;
end $migration$;

commit;
